for m in matches:
 n,h,w,body=m.group(1,2,3,4); h=int(h); w=int(w); rows=[[int(x) for x in line.split()] for line in body.strip().splitlines()[:h]]; off=m.end(); outmatch=re.search(r'Demo pair '+n+r' output \('+str(h)+r'x'+str(w)+r'\):\n',txt[off:]);
 if not outmatch: continue
 obody=txt[off+outmatch.end():]; outrows=[[int(x) for x in line.split()] for line in obody.splitlines()[:h]]; changes=collections.Counter((rows[i][j],outrows[i][j]) for i in range(h) for j in range(w) if rows[i][j]!=outrows[i][j]); print('DEMO',n,'changes',changes);
 # components each non-bg color 4-connected
 bg=collections.Counter(sum(rows,[])).most_common(1)[0][0]; seen=set(); comps=[]
 for i in range(h):
  for j in range(w):
   v=rows[i][j];
   if v==bg or (i,j) in seen: continue
   q=[(i,j)]; seen.add((i,j)); pts=[]
   while q:
    a,b=q.pop(); pts.append((a,b));
    for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=x<h and 0<=y<w and (x,y) not in seen and rows[x][y]==v: seen.add((x,y)); q.append((x,y))
   comps.append((v,len(pts),(min(x for x,y in pts),min(y for x,y in pts),max(x for x,y in pts),max(y for x,y in pts)),any(outrows[x][y]!=v for x,y in pts)))
 print('bg',bg,'components',sorted(comps,key=lambda z:(z[0],z[2])))
"'''
r=terminal(cmd,timeout=180)
print(r.get('output',''))

